		if (C >= (root + margin[sector]) * L) {
			// Beyond the lower boundary: below the cusp the lower face, above it
			// always out of gamut.
			g0 = estrinG(G0, sector * G_TERMS, t);
			g1 = estrinG(G1, sector * G_TERMS, t);
