				lowerSeed = low + (high + (0.10627775940035158 + -0.04881380003250039 * t) * t8) * t8;
				break seedEval;
				}
				if (face === 2) {
				const t = ((b * 0.0721134756059892 - a * 0.9973964340401585) - 0.0) * 1.1973997114222192;
				const t2=t*t;
				const t4=t2*t2;
				const t8=t4*t4;
				const low=((0.20473373534441747 + -0.010527848136023248 * t) + (0.07175661323734049 + -0.0073125472211453425 * t) * t2) + ((0.04187628782732185 + -0.006512637178049983 * t) + (-0.017158143394463532 + 0.009787410398960555 * t) * t2) * t4;
				const high=((0.20312969053463653 + -0.06691961927636256 * t) + (-0.4872442483759317 + 0.16629203403943887 * t) * t2) + ((0.7285475161832233 + -0.24531012160085514 * t) + (-0.5534327001495664 + 0.18606676197464364 * t) * t2) * t4;
