				}
				if (a * -0.9398715660186157 - b * -0.3415280945833225 > 0.0) {
				const t = ((b * -0.9599879420861877 - a * -0.28004133810765586) - 0.0) * 1.2397359381171371;
				const t2=t*t;
				const t4=t2*t2;
				const t8=t4*t4;
				const low=((0.17034577860885766 + -0.008996266311325283 * t) + (0.05951982007508851 + -0.006131976100847523 * t) * t2) + ((0.03490200547930951 + -0.004969822751381831 * t) + (-0.01649461795691659 + 0.004521326377787217 * t) * t2) * t4;
