				}
			const saturation = polish(lowerSeed,d,b,a);
			const lowerR = face === 0 ? 0 : ((rd * saturation + rb) * saturation + ra) * saturation + 1;
			const lowerG = face === 1 ? 0 : ((gd * saturation + gb) * saturation + ga) * saturation + 1;
			const lowerB = face === 2 ? 0 : ((bd * saturation + bb) * saturation + ba) * saturation + 1;
			if (!(saturation > 0 && saturation < rootLimit) || lowerR < -1e-12 || lowerG < -1e-12 || lowerB < -1e-12) return exact(rd,rb,ra,gd,gb,ga,bd,bb,ba,L3,target,inputU,out);

			// Below the cusp the lower face is the first exit.
			if (!(lowerR > target || lowerG > target || lowerB > target)) {
				if (inputU < saturation) {
					face = -1;
					break mapped;
				}
				r = lowerR;
				g = lowerG;
				blue = lowerB;
				break mapped;
			}

			// Above the cusp: the chord from the lower root to the brightest lower
			// channel's crossing, refined by two fourth-order Householder steps
			// (one division each). A converged, in-range prediction rejected by
			// another upper face retries once on the brightest channel, never
			// moving away from neutral; every other failure takes the exact search.
			face = lowerR > lowerG ? (lowerR > lowerB ? 0 : 2) : lowerG > lowerB ? 1 : 2;
			let u = (saturation * (target - 1)) / ((face === 0 ? lowerR : face === 1 ? lowerG : lowerB) - 1);
			const guard = target * (1 + 1e-12);
			let limit = saturation;
			for (let retry = 0; ; retry++) {
				const wd = face === 0 ? rd : face === 1 ? gd : bd;
				const wb = face === 0 ? rb : face === 1 ? gb : bb;
				const wa = face === 0 ? ra : face === 1 ? ga : ba;
				for (let step = 0; step < 2; step++) {
					const du = wd * u, q = du + wb, v = q * u + wa;
					const f = (v * u + 1) - target;
					const f1 = (du + q) * u + v;
					const halfSecond = (du + du) + q;
					// The first correction is fourth-order; the second uses Halley.
					const f1Squared = f1 * f1;
					const product = f * halfSecond;
					if (step === 1) {
						const denominator = f1Squared - product;
						if (denominator === 0) break;
						u -= f * f1 / denominator;
					} else {
						const denominator = f1 * (f1Squared - 2 * product) + f * f * wd;
						if (denominator === 0) break;
						u -= (f * (f1Squared - product)) / denominator;
					}
				}
				r = ((rd * u + rb) * u + ra) * u + 1;
				g = ((gd * u + gb) * u + ga) * u + 1;
				blue = ((bd * u + bb) * u + ba) * u + 1;
				if (!(u >= 0 && u <= limit && r >= -1e-12 && g >= -1e-12 && blue >= -1e-12 &&
					Math.abs((face === 0 ? r : face === 1 ? g : blue) - target) <= target * 1e-12)) return exact(rd,rb,ra,gd,gb,ga,bd,bb,ba,L3,target,inputU,out);
				const brightest = r > g ? (r > blue ? 0 : 2) : g > blue ? 1 : 2;
				if ((brightest === 0 ? r : brightest === 1 ? g : blue) <= guard) break;
				if (retry) return exact(rd,rb,ra,gd,gb,ga,bd,bb,ba,L3,target,inputU,out);
				face = brightest;
				limit = u;
			}
			// u is the validated first exit; classify the input against it.
			if (inputU < u) face = -1;
			else faceValue = 1;
		}

		if (face < 0) {
			r = ((rd * inputU + rb) * inputU + ra) * inputU + 1;
			g = ((gd * inputU + gb) * inputU + ga) * inputU + 1;
			blue = ((bd * inputU + bb) * inputU + ba) * inputU + 1;
		}
		out[0] = face === 0 ? faceValue : clampedGamma(L3 * r);
		out[1] = face === 1 ? faceValue : clampedGamma(L3 * g);
		out[2] = face === 2 ? faceValue : clampedGamma(L3 * blue);
		return out;
	}

}

